css:
@page {
	size: A4 portrait;
	margin: 15mm 15mm 15mm 20mm;
}

.ustva {
	color: #000;
	font-size: 9pt;
	line-height: 1.35;
}

.ustva h1 {
	font-size: 15pt;
	font-weight: 600;
	margin: 0 0 1mm;
}

.ustva h2 {
	font-size: 10.5pt;
	font-weight: 600;
	margin: 6mm 0 2mm;
}

.ustva .subtitle {
	color: #444;
	font-weight: 600;
	margin: 0 0 3mm;
}

.ustva table {
	width: 100%;
	border-collapse: collapse;
}

.ustva thead {
	display: table-header-group;
}

.ustva tr,
.ustva .group {
	break-inside: avoid;
	page-break-inside: avoid;
}

.ustva .form {
	table-layout: fixed;
}

.ustva .head {
	margin: 3mm 0 5mm;
}

.ustva .head td {
	padding: 0.8mm 2mm 0.8mm 0;
	vertical-align: top;
}

.ustva .head td.label {
	color: #555;
	width: 52mm;
}

.ustva .form th {
	border-bottom: 0.4mm solid #000;
	font-size: 8pt;
	font-weight: 600;
	padding: 1mm 1.5mm;
	text-align: left;
	vertical-align: bottom;
}

.ustva .form td {
	border-bottom: 0.2mm solid #bbb;
	padding: 1mm 1.5mm;
	vertical-align: top;
}

.ustva .form .section td {
	background: #ececec;
	border-bottom: 0.3mm solid #888;
	font-weight: 600;
	padding-top: 1.8mm;
}

.ustva .form .sum td {
	border-top: 0.3mm solid #000;
	font-weight: 600;
}

.ustva .form .empty td {
	color: #666;
}

.ustva col.line,
.ustva col.kz {
	width: 10mm;
}

.ustva col.num {
	width: 31mm;
}

.ustva .line {
	color: #555;
}

.ustva .kz {
	text-align: center;
}

.ustva .num,
.ustva .form th.num {
	text-align: right;
}

.ustva td.num {
	white-space: nowrap;
}

.ustva .flag {
	white-space: nowrap;
}

.ustva .note {
	color: #444;
}

.ustva .footer {
	border-top: 0.3mm solid #888;
	color: #444;
	font-size: 8pt;
	margin-top: 6mm;
	padding-top: 2mm;
}

.ustva .footer p {
	margin: 0 0 1mm;
}
